package uk.ac.ravensbourne.casevault.domain;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="remediation_actions") public class RemediationAction { @Id private UUID id; @ManyToOne @JoinColumn(name="case_id") private CaseRecord caseRecord; @ManyToOne @JoinColumn(name="organisation_id") private Organisation organisation; @ManyToOne @JoinColumn(name="author_id") private UserAccount author; @Column(nullable=false) private String description; @Enumerated(EnumType.STRING) private RemediationStatus status; protected RemediationAction(){} public RemediationAction(UUID id,CaseRecord c,UserAccount a,String d){this.id=id;caseRecord=c;organisation=c.getOrganisation();author=a;description=d;status=RemediationStatus.OPEN;} public String getDescription(){return description;} public RemediationStatus getStatus(){return status;} public void update(RemediationStatus s){status=s;} }
